import pulp

# Problem data
num_routes = 4
num_centers = 4
num_stages_per_route = 4

# Route data: (center, duration) for each stage
route_data = {
    1: [(3, 10), (2, 1), (1, 1), (4, 5)],  # R1
    2: [(2, 7), (1, 9), (4, 3), (3, 5)],  # R2
    3: [(1, 5), (2, 3), (4, 9), (3, 2)],  # R3
    4: [(3, 7), (2, 2), (4, 2), (1, 9)],  # R4
}

# Build duration and center lookup
duration = {}
center = {}
for i in range(1, num_routes + 1):
    for j in range(1, num_stages_per_route + 1):
        center[(i, j)] = route_data[i][j-1][0]
        duration[(i, j)] = route_data[i][j-1][1]

# Create model
model = pulp.LpProblem("logistics_scheduling", pulp.LpMinimize)

# Decision variables
# Start time of stage j of route i
start = {}
for i in range(1, num_routes + 1):
    for j in range(1, num_stages_per_route + 1):
        start[(i, j)] = pulp.LpVariable(f"start_{i}_{j}", lowBound=0, cat='Continuous')

# Makespan
makespan = pulp.LpVariable("makespan", lowBound=0, cat='Continuous')

# Binary variables for ordering stages at the same center
# order[(i1, j1, i2, j2)] = 1 if stage (i1,j1) precedes stage (i2,j2)
order = {}
stages_at_center = {c: [] for c in range(1, num_centers + 1)}
for i in range(1, num_routes + 1):
    for j in range(1, num_stages_per_route + 1):
        stages_at_center[center[(i, j)]].append((i, j))

# Create order variables for pairs of stages at same center
for c in range(1, num_centers + 1):
    stages = stages_at_center[c]
    for idx1, (i1, j1) in enumerate(stages):
        for idx2, (i2, j2) in enumerate(stages):
            if idx1 < idx2:  # Only create one variable per unordered pair
                order[(i1, j1, i2, j2)] = pulp.LpVariable(f"order_{i1}_{j1}_{i2}_{j2}", cat='Binary')

# Big-M value (upper bound on makespan)
M = sum(duration.values())  # Total sum of all durations

# Objective: minimize makespan
model += makespan, "objective_minimize_makespan"

# R1: Each stage must start at or after time 0
for i in range(1, num_routes + 1):
    for j in range(1, num_stages_per_route + 1):
        model += start[(i, j)] >= 0, f"R1_non_negative_start_{i}_{j}"

# R2: For each route, stage j+1 must start at or after the completion time of stage j
for i in range(1, num_routes + 1):
    for j in range(1, num_stages_per_route):
        # start[i,j+1] >= start[i,j] + duration[i,j]
        model += start[(i, j+1)] >= start[(i, j)] + duration[(i, j)], f"R2_precedence_{i}_{j}"

# R3: For any two stages requiring the same center, they cannot overlap in time
# R4: Each stage must run for exactly its specified duration (enforced by completion time definition)
# Combined: if order[(i1,j1),(i2,j2)] = 1 then start[i2,j2] >= start[i1,j1] + duration[i1,j1]
#           if order[(i1,j1),(i2,j2)] = 0 then start[i1,j1] >= start[i2,j2] + duration[i2,j2]
for c in range(1, num_centers + 1):
    stages = stages_at_center[c]
    for idx1, (i1, j1) in enumerate(stages):
        for idx2, (i2, j2) in enumerate(stages):
            if idx1 < idx2:
                # If order = 1: (i1,j1) before (i2,j2)
                model += start[(i2, j2)] >= start[(i1, j1)] + duration[(i1, j1)] - M * (1 - order[(i1, j1, i2, j2)]), f"R3_no_overlap_1_{i1}_{j1}_{i2}_{j2}"
                # If order = 0: (i2,j2) before (i1,j1)
                model += start[(i1, j1)] >= start[(i2, j2)] + duration[(i2, j2)] - M * order[(i1, j1, i2, j2)], f"R3_no_overlap_2_{i1}_{j1}_{i2}_{j2}"

# R5: The makespan must be at least the completion time of every stage
for i in range(1, num_routes + 1):
    for j in range(1, num_stages_per_route + 1):
        # completion time = start + duration
        model += makespan >= start[(i, j)] + duration[(i, j)], f"R5_makespan_bound_{i}_{j}"

# Solve
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Output results
print(f"Status: {pulp.LpStatus[model.status]}")
print(f"Makespan: {pulp.value(makespan)}")
print("\nSchedule:")
for i in range(1, num_routes + 1):
