equipment = {
    'A': {1: 'X', 2: 'Z', 3: 'Y'},
    'B': {1: 'X', 2: 'Y', 3: 'Z'},
    'C': {1: 'Z', 2: 'X', 3: 'Y'}
}

# Duration for each test: patient -> test index -> duration
duration = {
    'A': {1: 2, 2: 4, 3: 6},
    'B': {1: 1, 2: 2, 3: 3},
    'C': {1: 10, 2: 9, 3: 10}
}

patients = ['A', 'B', 'C']
tests = [1, 2, 3]
big_M = 100

# Create model
model = pulp.LpProblem("hospital_scheduling", pulp.LpMinimize)

# Decision variables
start_time = pulp.LpVariable.dicts("start_time", (patients, tests), lowBound=0, cat='Continuous')
makespan = pulp.LpVariable("makespan", lowBound=0, cat='Continuous')

# Binary variables for disjunctive constraints (same equipment)
# y[i1,j1,i2,j2] = 1 if test (i1,j1) is before test (i2,j2)
y = {}
for i1 in patients:
    for j1 in tests:
        for i2 in patients:
            for j2 in tests:
                if (i1, j1) < (i2, j2):  # Avoid duplicates
                    if equipment[i1][j1] == equipment[i2][j2]:
                        y[(i1, j1, i2, j2)] = pulp.LpVariable(f"y_{i1}_{j1}_{i2}_{j2}", cat='Binary')

# Objective: minimize makespan
model += makespan, "minimize_makespan"

# R1: Each test must start at or after time 0
for i in patients:
    for j in tests:
        model += start_time[i][j] >= 0, f"R1_start_nonnegative_{i}_{j}"

# R2: For each patient, test j+1 must start at or after the completion time of test j
for i in patients:
    for j in range(1, tests_per_patient):
        model += start_time[i][j+1] >= start_time[i][j] + duration[i][j], f"R2_precedence_{i}_{j}"

# R3 and R4: Disjunctive constraints for tests using same equipment
# R3: If two tests use the same equipment, they cannot overlap
# R4: For any two tests using the same equipment, one must finish before the other starts
for i1 in patients:
    for j1 in tests:
        for i2 in patients:
            for j2 in tests:
                if (i1, j1) < (i2, j2) and equipment[i1][j1] == equipment[i2][j2]:
                    # Either (i1,j1) before (i2,j2) or (i2,j2) before (i1,j1)
                    # If y=1: start[i2][j2] >= start[i1][j1] + duration[i1][j1]
                    # If y=0: start[i1][j1] >= start[i2][j2] + duration[i2][j2]
                    model += start_time[i2][j2] >= start_time[i1][j1] + duration[i1][j1] - big_M * (1 - y[(i1, j1, i2, j2)]), f"R3_R4_disjunctive_1_{i1}_{j1}_{i2}_{j2}"
                    model += start_time[i1][j1] >= start_time[i2][j2] + duration[i2][j2] - big_M * y[(i1, j1, i2, j2)], f"R3_R4_disjunctive_2_{i1}_{j1}_{i2}_{j2}"

# R5: The makespan must be at least the completion time of every test
for i in patients:
    for j in tests:
        model += makespan >= start_time[i][j] + duration[i][j], f"R5_makespan_{i}_{j}"

# R6: All start times and the makespan must be non-negative
# Already enforced by lowBound=0 in variable definitions, but adding explicit constraints
for i in patients:
    for j in tests:
        model += start_time[i][j] >= 0, f"R6_start_nonnegative_{i}_{j}"
model += makespan >= 0, "R6_makespan_nonnegative"

# Solve
