import pulp

# Problem data
num_routes = 4
num_stages = 4
big_M = 1000

# Duration data: duration[r][s] for route r, stage s (1-indexed)
duration = {
    1: {1: 5, 2: 5, 3: 7, 4: 7},
    2: {1: 4, 2: 5, 3: 6, 4: 1},
    3: {1: 8, 2: 10, 3: 2, 4: 3},
    4: {1: 7, 2: 8, 3: 1, 4: 2}
}

# Hub data: hub[r][s] for route r, stage s (1-indexed)
hub = {
    1: {1: 'C', 2: 'B', 3: 'A', 4: 'D'},
    2: {1: 'D', 2: 'A', 3: 'C', 4: 'B'},
    3: {1: 'A', 2: 'B', 3: 'C', 4: 'D'},
    4: {1: 'C', 2: 'B', 3: 'A', 4: 'D'}
}

# Create model
model = pulp.LpProblem("logistics_scheduling", pulp.LpMinimize)

# Decision variables
# start[r][s]: start time of stage s in route r
start = pulp.LpVariable.dicts("start", ((r, s) for r in range(1, num_routes+1) for s in range(1, num_stages+1)), lowBound=0, cat='Continuous')

# makespan: maximum completion time across all routes
makespan = pulp.LpVariable("makespan", lowBound=0, cat='Continuous')

# order[r1,s1,r2,s2]: binary variable for ordering at common hub
order = {}
for r1 in range(1, num_routes+1):
    for s1 in range(1, num_stages+1):
        for r2 in range(1, num_routes+1):
            for s2 in range(1, num_stages+1):
                if (r1, s1) < (r2, s2) and hub[r1][s1] == hub[r2][s2]:
                    order[(r1, s1, r2, s2)] = pulp.LpVariable(f"order_{r1}_{s1}_{r2}_{s2}", cat='Binary')

# Objective: minimize makespan
model += makespan, "minimize_makespan"

# R1: Each stage must start at or after time 0
# This is enforced by lowBound=0 on start variables, but we add explicit constraints as required
for r in range(1, num_routes+1):
    for s in range(1, num_stages+1):
        model += start[(r, s)] >= 0, f"R1_start_nonnegative_{r}_{s}"

# R2: Consecutive stages in the same route must satisfy precedence
for r in range(1, num_routes+1):
    for s in range(1, num_stages):
        model += start[(r, s+1)] >= start[(r, s)] + duration[r][s], f"R2_precedence_{r}_{s}"

# R3: For any two stages using the same hub, they cannot overlap
for (r1, s1, r2, s2), var in order.items():
    h = hub[r1][s1]  # common hub
    # If order=1: r1,s1 before r2,s2, so start[r2,s2] >= start[r1,s1] + duration[r1,s1]
    # If order=0: r2,s2 before r1,s1, so start[r1,s1] >= start[r2,s2] + duration[r2,s2]
    model += start[(r2, s2)] >= start[(r1, s1)] + duration[r1][s1] - big_M * (1 - var), f"R3_no_overlap_1_{r1}_{s1}_{r2}_{s2}"
