import pulp

# Create the model
model = pulp.LpProblem("tsp_inspection_tour", pulp.LpMinimize)

# Number of hubs
n = 7

# Distance matrix (symmetric)
d = {
    (1, 2): 99.5, (1, 3): 79.5, (1, 4): 30.9, (1, 5): 33.5, (1, 6): 96.2, (1, 7): 31.6,
    (2, 3): 153.1, (2, 4): 112.1, (2, 5): 66.1, (2, 6): 122.5, (2, 7): 127.6,
    (3, 4): 49.5, (3, 5): 97.4, (3, 6): 174.3, (3, 7): 55.2,
    (4, 5): 50.0, (4, 6): 127.0, (4, 7): 22.7,
    (5, 6): 97.4, (5, 7): 62.0,
    (6, 7): 120.2
}

# Create symmetric distances
for i in range(1, n+1):
    for j in range(1, n+1):
        if i < j:
            d[(j, i)] = d[(i, j)]
        elif i == j:
            d[(i, j)] = 0

# Decision variables: x[i,j] = 1 if travel from hub i to hub j
x = {}
for i in range(1, n+1):
    for j in range(1, n+1):
        if i != j:
            x[(i, j)] = pulp.LpVariable(f"x_{i}_{j}", cat='Binary')

# Decision variables: u[i] = position of hub i in tour (for subtour elimination)
u = {}
for i in range(1, n+1):
    u[i] = pulp.LpVariable(f"u_{i}", lowBound=1, upBound=n, cat='Integer')

# Objective: minimize total distance
model += pulp.lpSum(d[(i, j)] * x[(i, j)] for i in range(1, n+1) for j in range(1, n+1) if i != j), "total_distance"

# R1: Each hub must be entered exactly once
for j in range(1, n+1):
    model += pulp.lpSum(x[(i, j)] for i in range(1, n+1) if i != j) == 1, f"R1_enter_{j}"

# R2: Each hub must be exited exactly once
for i in range(1, n+1):
    model += pulp.lpSum(x[(i, j)] for j in range(1, n+1) if i != j) == 1, f"R2_exit_{i}"

# R3: Subtour elimination constraints (MTZ formulation)
# For all i, j where i != j and i, j >= 2 (excluding hub 1 as start)
for i in range(2, n+1):
    for j in range(2, n+1):
        if i != j:
            model += u[i] - u[j] + n * x[(i, j)] <= n - 1, f"R3_subtour_{i}_{j}"

# R4: The tour must return to the starting hub after visiting all other hubs
# This is implicitly handled by R1 and R2 (each hub entered and exited exactly once)
# But we need to ensure u[1] = 1 (hub 1 is the start)
model += u[1] == 1, "R4_start_position"

# Solve the model
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# Print results
print(f"Status: {pulp.LpStatus[model.status]}")
print(f"Total distance: {pulp.value(model.objective)}")
